"use client";
import { useEffect, useState } from "react";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Chrome } from "lucide-react";
import { useAuthStore } from "@/store/useAuthStore";
import { useRouter } from "next/navigation";

export function AuthSignupForm() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const signup = useAuthStore((state) => state.signup);
  const setAlert = useAuthStore.getState().setAlert;
  const isLongEnough = password.length >= 8;
  const isMatching = password === confirmPassword && confirmPassword.length > 0;
  const loginWithGoogle = useAuthStore((state) => state.loginWithGoogle);
  const router = useRouter();
  const user = useAuthStore((state) => state.registeredUser);
  const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/;

  const [error, setError] = useState({
    email: false,
    password: false,
    confirmPassword: false,
    name: false,
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // 1. Validasiya
    const newErrors = {
      email: !email,
      password: !password,
      confirmPassword: !confirmPassword,
      name: !name,
    };
    setError(newErrors);

    if (
      newErrors.email ||
      newErrors.password ||
      newErrors.confirmPassword ||
      newErrors.name
    ) {
      setAlert({
        message: "Please fill in all required fields correctly.",
        type: "error",
      });
      return;
    }

    if (password !== confirmPassword) {
      setAlert({ message: "Passwords do not match", type: "error" });
      return;
    }

    if (!passwordRegex.test(password)) {
      setAlert({
        message:
          "Password must be at least 8 characters long and include uppercase, lowercase and a number",
        type: "error",
      });
      return;
    }

    // 2. Prosesi başlat
    setIsLoading(true);

    try {
      // 3. Süni gecikmə (UI-ı görmək üçün)
      await new Promise((resolve) => setTimeout(resolve, 2000));

      // 4. Store-dakı signup funksiyasını gözləyirik
      const success = await signup(
        {
          fullName: name,
          email: email,
          password: password,
        },
        "manual",
      );

      // Qeyd: Əgər signup funksiyan geriyə dəyər qaytarmırsa,
      // catch blokuna düşməsi üçün Firebase xətası fırlatmalıdır.

      if (success) {
        await new Promise((resolve) => setTimeout(resolve, 800));
        setAlert({
          message: "Account created successfully! Please login.",
          type: "success",
        });
        setTimeout(() => {
          router.push("/login");
        }, 1000);
      }
    } catch (error: any) {
      setAlert({
        message: "Signup failed: " + (error.message || "Unknown error"),
        type: "error",
      });
    } finally {
      // 6. Hər iki halda loading-i dayandırırıq
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    const success = await loginWithGoogle();

    console.log("GOOGLE LOGIN:", success);

    if (success) {
      router.replace("/dashboard");
    }
  };

  return (
    <div className="space-y-6">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2 flex-col flex gap-1">
          <Label
            className="text-sm font-medium text-foreground/90"
            htmlFor="name"
          >
            Full Name
          </Label>

          <Input
            id="name"
            type="text"
            placeholder={error.name ? "Name is required!" : "John Doe"}
            value={name}
            onChange={(e) => setName(e.target.value)}
            className={`bg-white/5 border-white/10 placeholder:text-foreground/40 focus:border-white/20 focus:bg-white/10
              ${
                error.name
                  ? "border-red-500 focus:border-red-500 focus:ring-red-500"
                  : "border-white/10 focus:border-white/20 focus:ring-white/20"
              }
              
              `}
          />
        </div>

        <div className="space-y-2 flex-col flex gap-1">
          <Label htmlFor="signup-email"> Email</Label>
          <Input
            id="signup-email"
            type="email"
            placeholder={error.email ? "Email is required!" : "you@example.com"}
            value={email}
            onChange={(e) => {
              setEmail(e.target.value);
              if (e.target.value)
                setError((prev) => ({ ...prev, email: false }));
            }}
            className={`bg-white/5 border-white/10 placeholder:text-foreground/40 focus:border-white/20   focus:bg-white/10
            ${
              error.email
                ? "border-red-500 focus:border-red-500 focus:ring-red-500"
                : "border-white/10 focus:border-white/20 focus:ring-white/20"
            }`}
          />
        </div>

        <div className="space-y-2  flex-col flex gap-1">
          <Label htmlFor="signup-password"> Password</Label>
          <Input
            id="signup-password"
            type="password"
            placeholder={error.password ? "Password is required!" : "********"}
            value={password}
            onChange={(e) => {
              setPassword(e.target.value);
              if (e.target.value)
                setError((prev) => ({ ...prev, password: false }));
            }}
            className={`bg-white/5 border-white/10 placeholder:text-foreground/40 focus:border-white/20 focus:bg-white/10 
  ${
    password.length === 0
      ? "border-white/10" // Boşdursa default rəng
      : password.length >= 8
        ? "border-green-500 shadow-[0_0_5px_rgba(34,197,94,0.4)]" // Düzdürsə yaşıl
        : "border-red-500" // Səhvdirsə qırmızı
  } ${
    error.password
      ? "border-red-500 focus:border-red-500 focus:ring-red-500"
      : "border-white/10 focus:border-white/20 focus:ring-white/20"
  }  `}
          />
        </div>

        <div className="space-y-2 flex-col flex gap-1">
          <Label htmlFor="signup-confirm-password"> Confirm Password</Label>
          <Input
            id="signup-confirm-password"
            type="password"
            placeholder={
              error.confirmPassword ? "Passwords do not match!" : "********"
            }
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className={`bg-white/5 border-white/10 placeholder:text-foreground/40 focus:border-white/20 focus:bg-white/10 
  ${
    confirmPassword.length === 0
      ? "border-white/10" // Boşdursa default rəng
      : password === confirmPassword
        ? "border-green-500 shadow-[0_0_5px_rgba(34,197,94,0.4)]" // Düzdürsə yaşıl
        : "border-red-500" // Səhvdirsə qırmızı
  } ${
    error.confirmPassword
      ? "border-red-500 focus:border-red-500 focus:ring-red-500"
      : "border-white/10 focus:border-white/20 focus:ring-white/20"
  }`}
          />
          {password.length > 0 && (
            <div className="space-y-2 mt-3 ml-1">
              {/* 1. Uzunluq Dairəsi */}
              <div className="flex items-center gap-2">
                <div
                  className={`w-2.5 h-2.5 rounded-full transition-all duration-500 ${
                    isLongEnough
                      ? "bg-green-500 shadow-[0_0_8px_#22c55e]"
                      : "bg-red-500 shadow-[0_0_8px_#ef4444]"
                  }`}
                />
                <span
                  className={`text-[11px] ${isLongEnough ? "text-green-500" : "text-red-400"}`}
                >
                  Minimum 8 simvol
                </span>
              </div>

              {/* 2. Uyğunluq Dairəsi */}
              <div className="flex items-center gap-2">
                <div
                  className={`w-2.5 h-2.5 rounded-full transition-all duration-500 ${
                    isMatching
                      ? "bg-green-500 shadow-[0_0_8px_#22c55e]"
                      : "bg-red-500 shadow-[0_0_8px_#ef4444]"
                  }`}
                />
                <span
                  className={`text-[11px] ${isMatching ? "text-green-500" : "text-red-400"}`}
                >
                  Şifrələr eynidir
                </span>
              </div>
            </div>
          )}
        </div>

        <Button
          type="submit"
          disabled={isLoading}
          className="w-full bg-primary hover:bg-primary/90 text-primary-foreground  font-medium transition-all duration-200"
        >
          {isLoading ? "Creating Account..." : "Create Account"}
        </Button>
      </form>

      <div className="relative">
        <div className="absolute inset-0 flex items-center">
          <div className="w-full border border-white/10" />
        </div>
        <div className="relative flex justify-center text-xs uppercase">
          <span className="bg-card px-2 text-foreground/60 ">
            {" "}
            Or continue with
          </span>
        </div>
      </div>

      <button
        onClick={handleGoogleLogin}
        className="glow-effect w-full flex items-center  justify-center gap-2 py-2.5 rounded-lg bg-white/5 border  border-white/10   text-foreground/80 transition-color  duration-200 hover:bg-white/10 focus:outline-none focus:ring-2 focus:ring-white/20 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
      >
        <Chrome className="w-4 h-4" />
        <span className="text-sm font-medium"> Continue with Google</span>
      </button>
    </div>
  );
}
``;
